//! Bakes the engine ABI stamp into the crate.
//!
//! The stamp has to describe the engine *this build linked*, not the machine that ran the build
//! script: `CARGO_CFG_TARGET_ENDIAN` is the target's byte order, which is the only field of the
//! stamp that a cross build changes. `BC_VERSION` and the atom table come from the vendored
//! sources, which are the same for every cell.
//!
//! The result is one generated file with one constant, so nothing at run time has to read the
//! engine's sources or trust a second copy of the value. See `crates/ln-abi`.

use std::env;
use std::fs;
use std::path::{Path, PathBuf};

use ln_abi::{Endian, Stamp};

fn main() {
    let dir = ln_abi::vendored_engine_dir();
    println!("cargo:rerun-if-changed={}", dir.join("quickjs.c").display());
    println!("cargo:rerun-if-changed={}", dir.join("quickjs.h").display());
    println!(
        "cargo:rerun-if-changed={}",
        dir.join("quickjs-atom.h").display()
    );
    println!("cargo:rerun-if-env-changed=ONDE_QUICKJS_DIR");

    let mut stamp = Stamp::read(&dir).unwrap_or_else(|error| {
        panic!(
            "cannot read the engine identity from {}: {error}",
            dir.display()
        )
    });
    stamp.endian = target_endian();

    write_stamp(&stamp);
}

fn target_endian() -> Endian {
    match env::var("CARGO_CFG_TARGET_ENDIAN").as_deref() {
        Ok("big") => Endian::Big,
        Ok("little") => Endian::Little,
        other => panic!("CARGO_CFG_TARGET_ENDIAN is {other:?}; expected little or big"),
    }
}

fn write_stamp(stamp: &Stamp) {
    let out =
        PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR is set by cargo")).join("abi_stamp.rs");
    let source = format!(
        "/// The engine identity this build links, as an `ONDE-ABI:...;` string.\n\
         ///\n\
         /// Generated by `build.rs` from the vendored quickjs-ng sources; do not edit.\n\
         pub const ENGINE_STAMP: &str = {:?};\n",
        stamp.encode()
    );
    fs::write(&out, source).unwrap_or_else(|error| {
        panic!("write {}: {error}", out.display());
    });
    // Keep the path out of the message but make sure the file exists before the compiler looks
    // for it, so a failed write is reported here rather than as a confusing `include!` error.
    assert!(Path::new(&out).exists(), "generated stamp is missing");
}
